// License CC0-1.0 . It'd be my honor if you use any of my stuff for great effect.
const float dotRows = 20.;
const float dotCols = 20.;

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    uv*=vec2(dotCols,dotRows);
    float dist = length(fract(uv)*2.-1.);
    dist =smoothstep(0.,1.,dist);
    fragColor = vec4(vec3(dist),1.0);
}
